"use client";
import { useState } from "react";
import {
  PolarAngleAxis,
  PolarGrid,
  PolarRadiusAxis,
  Radar,
  RadarChart,
  ResponsiveContainer,
  Tooltip,
} from "recharts";
import { useHydratedReducedMotion } from "../../hooks/use-hydrated-reduced-motion";
import { ChartLegend, formatNumber, useChartHover } from "./chart-card";
import { ScoreRadarPlot } from "./score-radar-plot";
import { cx } from "../../utils/cx";
import { ChartActiveDot } from "./chart-active-dot";
import { RADAR_DEMO_RANGES } from "./chart-demo-data";
import {
  average,
  type ChartCommonProps,
  ChartFrame,
  type ChartRange,
  ink,
  numeric,
  PeriodSelect,
  StatTiles,
  sum,
  useChartRange,
} from "./pro-chart";
export interface RadarPoint {
  label: string;
  [key: string]: string | number;
}
export interface RadarSeries {
  key: string;
  label: string;
  color?: string;
}
export interface RadarChartRange extends ChartRange {
  rating?: string;
  data: RadarPoint[];
}
export interface RadarChartCardProps extends ChartCommonProps {
  data?: RadarPoint[];
  series?: RadarSeries[];
  ranges?: RadarChartRange[];
  variant?: "filled" | "dots" | "lines" | "score";
  max?: number;
  tiles?: boolean;
  alertBelow?: number;
}
export const RADAR_DATA: RadarPoint[] = RADAR_DEMO_RANGES[0]!.data;
const SCORE: RadarPoint[] = ["Focus", "Consistency", "Target", "Balance", "Deep work"].map(
  (label, i) => ({ label, desktop: [100, 9, 100, 100, 97][i]! }),
);
const SERIES: RadarSeries[] = [{ key: "desktop", label: "Desktop" }];
const RANGES: RadarChartRange[] = RADAR_DEMO_RANGES;

export function RadarChartCard({
  data,
  series = SERIES,
  ranges: supplied,
  title,
  variant = "filled",
  max,
  tiles = false,
  alertBelow = 30,
  ...props
}: RadarChartCardProps = {}) {
  const score = variant === "score",
    ranges = supplied ?? (data || score ? undefined : RANGES),
    period = useChartRange(ranges, props.defaultRange, props.onRangeChange),
    points = period.current?.data ?? data ?? (score ? SCORE : RADAR_DATA),
    hover = useChartHover(),
    [focus, setFocus] = useState<number | null>(null),
    reduced = useHydratedReducedMotion(),
    format = props.format ?? formatNumber,
    primary = series[0]?.key ?? "desktop",
    total = sum(points.map((p) => numeric(p[primary]))),
    mean = average(points.map((p) => numeric(p[primary]))),
    ceiling = max ?? Math.max(1, ...points.flatMap((p) => series.map((s) => numeric(p[s.key])))),
    point =
      hover.activeIndex != null
        ? points[hover.activeIndex]
        : focus != null
          ? points[focus]
          : undefined;
  return (
    <ChartFrame
      title={point?.label ?? title ?? (score ? "Weekly score" : "Visitors")}
      value={
        score
          ? undefined
          : point
            ? numeric(point[primary])
            : (period.current?.headline ?? props.headline ?? total)
      }
      format={format}
      delta={point ? undefined : score ? props.delta : (period.current?.delta ?? props.delta)}
      animateNumber
      pulseKey={hover.activeIndex ?? focus}
      className={cx(score && "h-[329px]", props.className)}
      action={
        <PeriodSelect
          ranges={ranges}
          selected={period.id}
          onChange={(id) => {
            hover.clear();
            setFocus(null);
            period.select(id);
          }}
          label={period.current?.label ?? props.range ?? (score ? "This week" : "H1 2024")}
        />
      }
      footer={
        tiles ? (
          <StatTiles
            responsive
            focusable={false}
            inactiveOpacity={0.4}
            items={points.map((p) => ({
              label: p.label,
              value: format(numeric(p[primary])),
            }))}
            active={hover.activeIndex ?? focus}
            onHover={setFocus}
          />
        ) : (
          series.length > 1 && (
            <ChartLegend
              variant="summary"
              entries={series.map((s, i) => ({
                label: s.label,
                color: s.color ?? ink(i),
                value: format(sum(points.map((p) => numeric(p[s.key])))),
              }))}
            />
          )
        )
      }
    >
      {score ? (
        <ScoreRadarPlot
          points={points}
          series={series}
          max={ceiling}
          mean={mean}
          alertBelow={alertBelow}
          format={format}
          reduced={reduced}
          rating={period.current?.rating}
        />
      ) : (
        <div className="relative h-[231px] w-full">
          <ResponsiveContainer width="100%" height="100%">
            <RadarChart
              data={points}
              outerRadius="74%"
              margin={{ top: 4, right: 4, bottom: 4, left: 4 }}
              {...hover.handlers}
            >
              <PolarGrid stroke="var(--color-chart-cursor)" />
              <PolarAngleAxis
                dataKey="label"
                tick={({ payload, x, y, textAnchor }) => (
                  <text
                    x={x}
                    y={y}
                    dy={4}
                    textAnchor={textAnchor}
                    fontSize={12}
                    fontWeight={500}
                    fill={
                      (hover.activeIndex ?? focus) != null &&
                      points[(hover.activeIndex ?? focus)!]?.label === payload.value
                        ? "var(--color-text-primary)"
                        : "var(--color-text-tertiary)"
                    }
                    className="transition-[fill] duration-150 ease-out"
                  >
                    {payload.value}
                  </text>
                )}
              />
              <PolarRadiusAxis domain={[0, ceiling]} tick={false} axisLine={false} />
              <Tooltip content={() => null} />
              {series.map((s, i) => (
                <Radar
                  key={s.key}
                  name={s.label}
                  dataKey={s.key}
                  stroke={s.color ?? ink(i).replace(")", "-active)")}
                  fill={s.color ?? ink(i)}
                  fillOpacity={variant === "lines" ? 0 : 0.28}
                  strokeWidth={2}
                  strokeLinejoin="round"
                  dot={variant === "dots" ? { r: 3, fill: s.color ?? ink(i) } : false}
                  activeDot={(point) => (
                    <ChartActiveDot {...point} fill={s.color ?? ink(i).replace(")", "-active)")} />
                  )}
                  isAnimationActive={!reduced}
                  animationDuration={450}
                  animationEasing="ease"
                />
              ))}
            </RadarChart>
          </ResponsiveContainer>
        </div>
      )}
    </ChartFrame>
  );
}
